#!/usr/bin/env node
// Builds app/lexeis-ast.json: our LSJ lemma key -> the headword of its entry in
// Ast's Lexicon Platonicum on Lexeis (https://lexeis.org/plato/, Cornell), so a
// lemma page can link to it. Neither the build nor the site fetches lexeis.org;
// the table is regenerated by hand from a committed headword list.
//
//   node scripts/build-lexeis-ast.mjs            # sources/lexeis-ast/headwords.json -> app/lexeis-ast.json
//   node scripts/build-lexeis-ast.mjs --harvest  # first refresh headwords.json from lexeis.org's A–Ω word lists
//
// A key links only on an exact match: Beta Code with quantity marks (^ _) and
// homograph digits removed, accents and breathings kept, exactly one Lexeis
// headword, and the case agreeing (a '*' key with a capital headword, so
// kalli/as "tame ape" never reaches Καλλίας). Anything else (Lexeis homographs
// ἀργός / ἀργός2, ties, misses, near-misses in accent) gets no link: Lexeis
// numbers homographs its own way, and an accent apart can be another word
// (φαρμάκεια a bird, φαρμακεία a drugging), so a guess could open the wrong one.
//
// sources/lexeis-ast/overrides.json adds the pairs checked by hand that the
// exact match cannot reach: Ast heads Plato's spelling or form where LSJ heads
// another (βοηθός / βοηθόος, πτοίησις / πτόησις),
// or LSJ's case differs from its key (fru/c1 is LSJ's Φρύξ, *peiqw/ its πειθώ).
import { readFileSync, writeFileSync } from 'node:fs';

const HEADWORDS = 'sources/lexeis-ast/headwords.json';
const OVERRIDES = 'sources/lexeis-ast/overrides.json';
const KEYS = 'app/lemma-slugs.json';
const OUT = 'app/lexeis-ast.json';

async function harvest() {
  const api = 'https://lexeis.org/plato/api/getMatchingLemmas.php';
  const combos = await (await fetch('https://lexeis.org/plato/assets/alphaCombos.json')).json();
  const tokens = new Set();
  for (const [letter, list] of Object.entries(combos.combos)) {
    for (const { link } of list) {
      const second = link.split('/').pop();
      const searchQuery = second === '_' ? letter.toLowerCase() : letter.toLowerCase() + second;
      const res = await fetch(api, { method: 'POST', body: JSON.stringify({ searchQuery }) });
      for (const { token } of await res.json()) tokens.add(token);
      await new Promise((r) => setTimeout(r, 200)); // a small academic server
    }
  }
  const sorted = [...tokens].sort();
  writeFileSync(HEADWORDS, `[\n${sorted.map((t) => JSON.stringify(t)).join(',\n')}\n]\n`);
  console.log(`harvested ${sorted.length} headwords -> ${HEADWORDS}`);
}

const BASE = {
  α: 'a', β: 'b', γ: 'g', δ: 'd', ε: 'e', ζ: 'z', η: 'h', θ: 'q', ι: 'i', κ: 'k',
  λ: 'l', μ: 'm', ν: 'n', ξ: 'c', ο: 'o', π: 'p', ρ: 'r', σ: 's', ς: 's', τ: 't',
  υ: 'u', φ: 'f', χ: 'x', ψ: 'y', ω: 'w',
};
const MARKS = { '̓': ')', '̔': '(', '́': '/', '̀': '/', '͂': '=', 'ͅ': '|', '̈': '+' };

// Unicode Greek -> our key form (the same mapping as plato_pipeline/beta.py).
// Returns null for anything that is not a single Greek word.
function greekToBeta(token) {
  let out = '';
  for (const ch of token.trim().replace(/\d+$/, '').normalize('NFD')) {
    const low = ch.toLowerCase();
    if (low in BASE) out += BASE[low];
    else if (ch in MARKS) out += MARKS[ch];
    else if (ch === '̄' || ch === '̆') continue; // macron, breve
    else return null;
  }
  return out || null;
}

// Our key -> the same form: '*(/ellhn' -> 'e(/llhn', 'a)/llos1' -> 'a)/llos'.
function normKey(key) {
  let k = key.replace(/[\^_]/g, '').replace(/\d+$/, '');
  const cap = /^\*([()/\\=|+]*)([a-z])/.exec(k);
  if (cap) k = cap[2] + cap[1] + k.slice(cap[0].length);
  return k;
}

function group(items, keyOf) {
  const m = new Map();
  for (const item of items) {
    const k = keyOf(item);
    if (k == null) continue;
    if (!m.has(k)) m.set(k, []);
    m.get(k).push(item);
  }
  return m;
}

function build() {
  const headwords = JSON.parse(readFileSync(HEADWORDS, 'utf-8'));
  const keys = Object.keys(JSON.parse(readFileSync(KEYS, 'utf-8')));
  const byBeta = group(headwords, greekToBeta);
  const capital = (t) => { const c = t.trim()[0]; return c !== c.toLowerCase(); };

  const table = {};
  const caseApart = [];
  let homograph = 0;
  for (const key of keys) {
    const hits = byBeta.get(normKey(key));
    if (!hits) continue;
    if (hits.length > 1) { homograph++; continue; }
    if (key.startsWith('*') !== capital(hits[0])) { caseApart.push(`${key} ${hits[0]}`); continue; }
    table[key] = hits[0];
  }
  // A numbered Lexeis headword (ἔλεγχος2), or one headword two of our keys
  // reach (δύω for du/w and du/w2), says nothing about which word it is.
  const reached = group(Object.keys(table), (k) => table[k]);
  for (const [token, ks] of reached) {
    if (/\d\s*$/.test(token) || ks.length > 1) for (const k of ks) { delete table[k]; homograph++; }
  }
  const overrides = JSON.parse(readFileSync(OVERRIDES, 'utf-8'));
  const known = new Set(headwords);
  let byHand = 0;
  for (const [key, token] of Object.entries(overrides)) {
    if (!keys.includes(key)) throw new Error(`${OVERRIDES}: ${key} is not a lemma key`);
    if (!known.has(token)) throw new Error(`${OVERRIDES}: ${token} is not a Lexeis headword`);
    if (key in table) continue;
    const at = caseApart.findIndex((pair) => pair.startsWith(`${key} `));
    if (at >= 0) caseApart.splice(at, 1);
    table[key] = token;
    byHand++;
  }
  const linked = Object.keys(table).length;
  const sorted = Object.fromEntries(Object.entries(table).sort(([a], [b]) => (a < b ? -1 : 1)));
  writeFileSync(OUT, `${JSON.stringify(sorted, null, 0).replace(/,"/g, ',\n"').replace(/^\{/, '{\n').replace(/\}$/, '\n}')}\n`);
  console.log(
    `${keys.length} keys: ${linked} linked (${byHand} by hand), ${homograph} skipped (Lexeis homographs), ` +
    `${caseApart.length} skipped (case apart), ${keys.length - linked - homograph - caseApart.length} no entry -> ${OUT}`,
  );
  if (process.argv.includes('--verbose')) for (const pair of caseApart) console.log(`  case apart: ${pair}`);
}

if (process.argv.includes('--harvest')) await harvest();
build();
